Lemma tw_img : forall a k, 0x10000 <= a -> a + k <= SEGTOP_A -> (a + k <= 0x1deb48 \/ 0x5eeb70 <= a) -> disjoint_from W_tail a k.
Proof using HA Hn Hca LOW LOR SPT SPA.
